import { AnimatePresence, motion, useReducedMotion } from 'motion/react'
import { Activity, AlertTriangle, ArrowDown, ArrowLeft, ArrowRight, ArrowUpRight, BadgeCheck, BarChart3, Bookmark, BookmarkCheck, Check, ChevronDown, ChevronRight, CircleHelp, ClipboardList, Download, FileSearch, FileSpreadsheet, FlaskConical, Layers3, Menu, MessageCircle, Microscope, Paperclip, ScanEye, Search, Send, Settings2, Sparkles, X } from 'lucide-react'
import { Bar, BarChart, CartesianGrid, Legend, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts'
